import { useState, useRef } from 'react'
import { Button } from '@/components/ui/button'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { Upload, FileText, Info } from 'lucide-react'
import { parseCsv, validateGearItems, checkForDuplicates } from '@/utils/csvParser'
import type { ParsedGearItem } from '@/utils/csvParser'

interface CsvImportProps {
  onImportData: (items: ParsedGearItem[], errors?: string[], warnings?: string[]) => void
}

export function CsvImport({ onImportData }: CsvImportProps) {
  const [isDragOver, setIsDragOver] = useState(false)
  const [isProcessing, setIsProcessing] = useState(false)
  const [fileName, setFileName] = useState<string | null>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const handleFileSelect = (file: File) => {
    if (!file.name.toLowerCase().endsWith('.csv')) {
      onImportData([], ['Please select a CSV file (.csv extension)'])
      return
    }

    setFileName(file.name)
    setIsProcessing(true)

    const reader = new FileReader()
    reader.onload = (e) => {
      const csvContent = e.target?.result as string
      processCsvContent(csvContent)
    }
    reader.onerror = () => {
      onImportData([], ['Failed to read file. Please try again.'])
      setIsProcessing(false)
    }
    reader.readAsText(file)
  }

  const processCsvContent = (csvContent: string) => {
    try {
      // Parse CSV
      const parseResult = parseCsv(csvContent)

      if (!parseResult.success) {
        onImportData([], parseResult.errors, parseResult.warnings)
        setIsProcessing(false)
        return
      }

      // Validate items
      const { valid, invalid } = validateGearItems(parseResult.data)

      const errors: string[] = [...parseResult.errors]
      const warnings: string[] = [...parseResult.warnings]

      // Add validation errors
      invalid.forEach(({ item, errors: itemErrors }) => {
        errors.push(`"${item.name}": ${itemErrors.join(', ')}`)
      })

      // Add warnings for any issues
      if (invalid.length > 0) {
        warnings.push(`${invalid.length} items had validation errors and were skipped`)
      }

      // Check for duplicates in valid items
      const { unique, duplicates, warnings: duplicateWarnings } = checkForDuplicates(valid)
      warnings.push(...duplicateWarnings)

      if (duplicates.length > 0) {
        duplicates.forEach(({ item }) => {
          warnings.push(`Removed duplicate: "${item.name}" (${item.weight_grams}g)`)
        })
      }

      if (unique.length > 0) {
        warnings.push(`Successfully parsed ${unique.length} unique items`)
      }

      onImportData(unique, errors, warnings)

    } catch (error) {
      onImportData([], [`Unexpected error: ${error instanceof Error ? error.message : 'Unknown error'}`])
    } finally {
      setIsProcessing(false)
    }
  }

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault()
    setIsDragOver(true)
  }

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault()
    setIsDragOver(false)
  }

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault()
    setIsDragOver(false)

    const files = Array.from(e.dataTransfer.files)
    if (files.length > 0) {
      handleFileSelect(files[0])
    }
  }

  const handleFileInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files
    if (files && files.length > 0) {
      handleFileSelect(files[0])
    }
  }

  const handleClickUpload = () => {
    fileInputRef.current?.click()
  }

  return (
    <div className="space-y-4">
      {/* Instructions */}
      <Alert>
        <Info className="h-4 w-4" />
        <AlertDescription>
          <div className="font-medium mb-2">How to export from LighterPack:</div>
          <ol className="list-decimal list-inside space-y-1 text-sm">
            <li>Go to your LighterPack list</li>
            <li>Click the "Export" button</li>
            <li>Select "CSV" format</li>
            <li>Upload the downloaded file below</li>
          </ol>
        </AlertDescription>
      </Alert>

      {/* File Upload Area */}
      <div
        className={`
          border-2 border-dashed rounded-lg p-8 text-center transition-colors
          ${isDragOver ? 'border-primary bg-primary/5' : 'border-muted-foreground/25'}
          ${isProcessing ? 'opacity-50 pointer-events-none' : 'cursor-pointer hover:border-primary hover:bg-primary/5'}
        `}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        onClick={handleClickUpload}
      >
        <input
          ref={fileInputRef}
          type="file"
          accept=".csv"
          onChange={handleFileInputChange}
          className="hidden"
          disabled={isProcessing}
        />

        <div className="space-y-3">
          {isProcessing ? (
            <>
              <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-primary mx-auto" />
              <div className="text-sm font-medium">Processing {fileName}...</div>
            </>
          ) : (
            <>
              <Upload className="h-10 w-10 text-muted-foreground mx-auto" />
              <div>
                <div className="font-medium">Drop your CSV file here</div>
                <div className="text-sm text-muted-foreground mt-1">
                  or click to browse files
                </div>
              </div>
              <div className="text-xs text-muted-foreground">
                Supports LighterPack CSV exports (.csv files up to 10MB)
              </div>
            </>
          )}
        </div>
      </div>

      {/* Manual Upload Button */}
      <div className="text-center">
        <Button
          variant="outline"
          onClick={handleClickUpload}
          disabled={isProcessing}
          className="w-full sm:w-auto"
        >
          <FileText className="h-4 w-4 mr-2" />
          Choose CSV File
        </Button>
      </div>

      {/* CSV Format Info */}
      <Alert>
        <Info className="h-4 w-4" />
        <AlertDescription>
          <div className="font-medium mb-2">Expected CSV format:</div>
          <div className="text-sm space-y-1">
            <div><strong>Required columns:</strong> Name, Weight</div>
            <div><strong>Optional columns:</strong> Brand, Category, Quantity, Worn, Consumable, Price, Description, Notes</div>
            <div className="text-muted-foreground">Column names are flexible - we'll automatically detect common variations.</div>
          </div>
        </AlertDescription>
      </Alert>
    </div>
  )
}

import { useState, useEffect } from 'react'
import { useAuth } from '@/contexts/AuthContext'
import { supabase } from '@/lib/supabase'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { Upload, Link } from 'lucide-react'
import { CsvImport } from './CsvImport'
import { UrlImport } from './UrlImport'
import { ImportPreview } from './ImportPreview'
import { ImportResults } from './ImportResults'
import type { ParsedGearItem } from '@/utils/csvParser'
import type { GearItem } from '@/types/database'

interface ImportGearFormProps {
  onImportComplete: (items: ParsedGearItem[]) => Promise<void>
  onCancel?: () => void
  className?: string
}

export interface ImportState {
  step: 'input' | 'preview' | 'importing' | 'complete'
  items: ParsedGearItem[]
  newItems: ParsedGearItem[]
  duplicates: ParsedGearItem[]
  errors: string[]
  warnings: string[]
  metadata?: {
    listName?: string
    totalWeight?: number
    itemCount?: number
  }
}

export function ImportGearForm({ onImportComplete, onCancel, className }: ImportGearFormProps) {
  const { user } = useAuth()
  const [activeTab, setActiveTab] = useState<'csv' | 'url'>('csv')
  const [existingItems, setExistingItems] = useState<GearItem[]>([])
  const [importState, setImportState] = useState<ImportState>({
    step: 'input',
    items: [],
    newItems: [],
    duplicates: [],
    errors: [],
    warnings: []
  })

  // Fetch existing gear items on mount
  useEffect(() => {
    const fetchExistingItems = async () => {
      if (!user) return

      try {
        const { data, error } = await supabase
          .from('gear_items')
          .select('*')
          .eq('user_id', user.id)

        if (error) throw error
        setExistingItems(data || [])
      } catch (error) {
        console.error('Failed to fetch existing gear items:', error)
      }
    }

    fetchExistingItems()
  }, [user])

  // Function to check if two items are duplicates
  const isDuplicate = (importItem: ParsedGearItem, existingItem: GearItem): boolean => {
    // Match on name and brand (case insensitive)
    const importName = importItem.name.toLowerCase().trim()
    const importBrand = (importItem.brand || '').toLowerCase().trim()
    const existingName = existingItem.name.toLowerCase().trim()
    const existingBrand = (existingItem.brand || '').toLowerCase().trim()

    return importName === existingName && importBrand === existingBrand
  }

  const handleImportData = (data: ParsedGearItem[], errors: string[] = [], warnings: string[] = [], metadata?: any) => {
    // Deduplicate against existing items
    const newItems: ParsedGearItem[] = []
    const duplicates: ParsedGearItem[] = []

    data.forEach(importItem => {
      const isDuplicateItem = existingItems.some(existing => isDuplicate(importItem, existing))
      if (isDuplicateItem) {
        duplicates.push(importItem)
      } else {
        newItems.push(importItem)
      }
    })

    // Add deduplication warnings (summary only, no ugly lists)
    const updatedWarnings = [...warnings]
    if (duplicates.length > 0) {
      updatedWarnings.push(
        `${duplicates.length} items skipped as duplicates (already exist in your gear library)`
      )
    }

    if (newItems.length > 0) {
      updatedWarnings.push(`${newItems.length} new items ready to import`)
    }

    setImportState({
      step: 'preview', // Always show preview, even if no new items
      items: data,
      newItems,
      duplicates,
      errors,
      warnings: updatedWarnings,
      metadata
    })
  }

  const handleConfirmImport = async () => {
    setImportState(prev => ({ ...prev, step: 'importing' }))

    try {
      // Only import new items (not duplicates)
      await onImportComplete(importState.newItems)
      setImportState(prev => ({ ...prev, step: 'complete' }))
    } catch (error) {
      setImportState(prev => ({
        ...prev,
        step: 'preview',
        errors: [...prev.errors, `Import failed: ${error instanceof Error ? error.message : 'Unknown error'}`]
      }))
    }
  }

  const handleReset = () => {
    setImportState({
      step: 'input',
      items: [],
      newItems: [],
      duplicates: [],
      errors: [],
      warnings: [],
      metadata: undefined
    })
  }

  const handleClose = () => {
    handleReset()
    onCancel?.()
  }

  if (importState.step === 'preview') {
    return (
      <ImportPreview
        items={importState.items}
        newItems={importState.newItems}
        duplicates={importState.duplicates}
        errors={importState.errors}
        warnings={importState.warnings}
        metadata={importState.metadata}
        onConfirm={handleConfirmImport}
        onCancel={handleReset}
        className={className}
      />
    )
  }

  if (importState.step === 'importing' || importState.step === 'complete') {
    return (
      <ImportResults
        state={importState.step}
        importedCount={importState.items.length}
        errors={importState.errors}
        onClose={handleClose}
        onImportMore={handleReset}
        className={className}
      />
    )
  }

  return (
    <Card className={className}>
      <CardHeader>
        <CardTitle>Import Gear</CardTitle>
        <CardDescription>
          Import your gear from LighterPack CSV export or by URL
        </CardDescription>
      </CardHeader>
      <CardContent>
        <Tabs defaultValue="csv" value={activeTab} onValueChange={(value) => setActiveTab(value as 'csv' | 'url')}>
          <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="csv" className="flex items-center gap-2">
              <Upload className="h-4 w-4" />
              CSV File
            </TabsTrigger>
            <TabsTrigger value="url" className="flex items-center gap-2">
              <Link className="h-4 w-4" />
              LighterPack URL
            </TabsTrigger>
          </TabsList>

          <TabsContent value="csv" className="mt-6">
            <CsvImport onImportData={handleImportData} />
          </TabsContent>

          <TabsContent value="url" className="mt-6">
            <UrlImport onImportData={handleImportData} />
          </TabsContent>
        </Tabs>

        <div className="flex justify-end gap-2 mt-6 pt-4 border-t">
          <Button variant="ghost" onClick={handleClose}>
            Cancel
          </Button>
        </div>
      </CardContent>
    </Card>
  )
}

import { useState } from 'react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { Textarea } from '@/components/ui/textarea'
import { Link, AlertCircle, Info, ExternalLink } from 'lucide-react'
import { parseLighterPackUrl, parseLighterPackHtml, createLighterPackInstructions } from '@/utils/lighterpackParser'
import type { ParsedGearItem } from '@/utils/csvParser'

interface UrlImportProps {
  onImportData: (items: ParsedGearItem[], errors?: string[], warnings?: string[], metadata?: any) => void
}

export function UrlImport({ onImportData }: UrlImportProps) {
  const [url, setUrl] = useState('')
  const [htmlContent, setHtmlContent] = useState('')
  const [isProcessing, setIsProcessing] = useState(false)
  const [importMode, setImportMode] = useState<'url' | 'html'>('url')

  const handleUrlImport = async () => {
    if (!url.trim()) {
      onImportData([], ['Please enter a LighterPack URL'])
      return
    }

    setIsProcessing(true)

    try {
      const result = await parseLighterPackUrl(url.trim())

      if (result.success) {
        onImportData(result.data, result.errors, [], result.metadata)
      } else {
        onImportData([], result.errors)
      }
    } catch (error) {
      onImportData([], [`Failed to import: ${error instanceof Error ? error.message : 'Unknown error'}`])
    } finally {
      setIsProcessing(false)
    }
  }

  const handleHtmlImport = () => {
    if (!htmlContent.trim()) {
      onImportData([], ['Please paste the HTML content from your LighterPack page'])
      return
    }

    setIsProcessing(true)

    try {
      const result = parseLighterPackHtml(htmlContent.trim())

      if (result.success) {
        onImportData(result.data, result.errors, [], result.metadata)
      } else {
        onImportData([], result.errors)
      }
    } catch (error) {
      onImportData([], [`Failed to parse HTML: ${error instanceof Error ? error.message : 'Unknown error'}`])
    } finally {
      setIsProcessing(false)
    }
  }

  return (
    <div className="space-y-6">
      {/* Mode Selection */}
      <div className="flex gap-2">
        <Button
          variant={importMode === 'url' ? 'default' : 'outline'}
          size="sm"
          onClick={() => setImportMode('url')}
        >
          <Link className="h-4 w-4 mr-2" />
          URL Import
        </Button>
        <Button
          variant={importMode === 'html' ? 'default' : 'outline'}
          size="sm"
          onClick={() => setImportMode('html')}
        >
          HTML Import
        </Button>
      </div>

      {importMode === 'url' ? (
        <div className="space-y-4">
          {/* URL Input */}
          <div className="space-y-2">
            <Label htmlFor="lighterpack-url">LighterPack URL</Label>
            <div className="flex gap-2">
              <Input
                id="lighterpack-url"
                type="url"
                placeholder="https://lighterpack.com/r/abc123"
                value={url}
                onChange={(e) => setUrl(e.target.value)}
                disabled={isProcessing}
                className="flex-1 min-w-0"
              />
              <Button
                onClick={handleUrlImport}
                disabled={!url.trim() || isProcessing}
              >
                {isProcessing ? (
                  <>
                    <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-current mr-2" />
                    Loading...
                  </>
                ) : (
                  'Import'
                )}
              </Button>
            </div>
          </div>

          {/* URL Import Notice */}
          <Alert variant="destructive">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription>
              <div className="font-medium mb-2">Direct URL import is not yet available</div>
              <div className="text-sm">
                Due to browser security restrictions, we can't directly fetch LighterPack pages. 
                Please use one of these alternatives:
              </div>
              <ul className="list-disc list-inside mt-2 space-y-1 text-sm">
                <li>Export your LighterPack list as CSV and use the "CSV File" tab</li>
                <li>Use the "HTML Import" option below</li>
              </ul>
            </AlertDescription>
          </Alert>

          {/* Example */}
          <Alert>
            <Info className="h-4 w-4" />
            <AlertDescription>
              <div className="font-medium mb-2">Example LighterPack URL:</div>
              <div className="text-sm font-mono bg-muted p-2 rounded overflow-hidden">
                <div className="truncate">
                  https://lighterpack.com/r/q7l72y
                </div>
              </div>
              <Button
                variant="ghost"
                size="sm"
                className="mt-2 h-auto p-0 text-xs"
                onClick={() => window.open('https://lighterpack.com/r/q7l72y', '_blank')}
              >
                <ExternalLink className="h-3 w-3 mr-1" />
                View example
              </Button>
            </AlertDescription>
          </Alert>
        </div>
      ) : (
        <div className="space-y-4">
          {/* Instructions */}
          <Alert>
            <Info className="h-4 w-4" />
            <AlertDescription>
              <div className="font-medium mb-2">How to get HTML content:</div>
              <ol className="list-decimal list-inside space-y-1 text-sm">
                <li>Go to your LighterPack list in your browser</li>
                <li>Right-click on the page and select "View Page Source" (or press Ctrl+U / Cmd+U)</li>
                <li>Copy all the HTML content (Ctrl+A, then Ctrl+C)</li>
                <li>Paste it in the text area below</li>
              </ol>
            </AlertDescription>
          </Alert>

          {/* HTML Input */}
          <div className="space-y-2">
            <Label htmlFor="html-content">LighterPack HTML Content</Label>
            <Textarea
              id="html-content"
              placeholder="Paste the full HTML source code from your LighterPack page here..."
              value={htmlContent}
              onChange={(e) => setHtmlContent(e.target.value)}
              disabled={isProcessing}
              rows={8}
              className="font-mono text-xs"
            />
          </div>

          {/* Import Button */}
          <Button
            onClick={handleHtmlImport}
            disabled={!htmlContent.trim() || isProcessing}
            className="w-full"
          >
            {isProcessing ? (
              <>
                <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-current mr-2" />
                Processing HTML...
              </>
            ) : (
              'Parse HTML & Import'
            )}
          </Button>

          {/* Security Note */}
          <Alert>
            <Info className="h-4 w-4" />
            <AlertDescription className="text-sm">
              <div className="font-medium mb-1">Privacy Note:</div>
              Your HTML content is processed locally in your browser and never sent to our servers.
            </AlertDescription>
          </Alert>
        </div>
      )}

      {/* General Instructions */}
      <Alert>
        <Info className="h-4 w-4" />
        <AlertDescription>
          <div className="font-medium mb-2">For the best experience:</div>
          <ul className="list-disc list-inside space-y-1 text-sm">
            <li>Make sure your LighterPack list is public or shared</li>
            <li>CSV export is usually the most reliable method</li>
            <li>We'll automatically detect categories and convert weights to grams</li>
            <li>You can review all items before final import</li>
          </ul>
        </AlertDescription>
      </Alert>
    </div>
  )
}

import type { ParsedGearItem } from './csvParser'

export interface LighterPackParseResult {
  success: boolean
  data: ParsedGearItem[]
  errors: string[]
  metadata?: {
    listName?: string
    totalWeight?: number
    itemCount?: number
  }
}

// Category emoji mappings from LighterPack
const CATEGORY_MAPPINGS: Record<string, string> = {
  '🥾': 'Footwear',
  '🥋': 'Clothing',
  '⚡️': 'Electronics',
  '🍽️': 'Cooking',
  '💤': 'Sleep System',
  '⛺': 'Shelter',
  '💧': 'Water',
  '🎒': 'Pack',
  '🧭': 'Navigation',
  '🏥': 'First Aid',
  '🧴': 'Toiletries',
  '🔧': 'Tools',
  '📚': 'Documents',
  '🍫': 'Food',
  '🎯': 'Other'
}

/**
 * Parse a LighterPack public list URL
 */
export async function parseLighterPackUrl(url: string): Promise<LighterPackParseResult> {
  const result: LighterPackParseResult = {
    success: false,
    data: [],
    errors: []
  }

  try {
    // Validate URL format
    if (!isValidLighterPackUrl(url)) {
      result.errors.push('Invalid LighterPack URL format. Expected: https://lighterpack.com/r/[ID]')
      return result
    }

    // For now, we'll create a proxy approach since we can't directly fetch cross-origin
    // In a real implementation, this would either:
    // 1. Use a backend proxy to fetch the LighterPack page
    // 2. Use a CORS proxy service
    // 3. Have users paste the HTML content

    result.errors.push('Direct URL import not yet implemented. Please use CSV export from LighterPack for now.')
    return result

  } catch (error) {
    result.errors.push(`Failed to parse LighterPack URL: ${error instanceof Error ? error.message : 'Unknown error'}`)
    return result
  }
}

/**
 * Parse LighterPack HTML content (for when we have the HTML)
 */
export function parseLighterPackHtml(html: string): LighterPackParseResult {
  const result: LighterPackParseResult = {
    success: true,
    data: [],
    errors: [],
    metadata: {}
  }

  try {
    // Create a DOM parser to work with the HTML
    const parser = new DOMParser()
    const doc = parser.parseFromString(html, 'text/html')

    // Extract list metadata
    const titleElement = doc.querySelector('title')
    result.metadata!.listName = titleElement?.textContent?.trim() || 'LighterPack List'

    // Try to parse the chartData JSON first
    const chartData = extractChartData(html)
    if (chartData) {
      result.data = parseChartData(chartData)
    }

    // Fallback to HTML parsing if chartData fails
    if (result.data.length === 0) {
      result.data = parseHtmlStructure(doc)
    }

    // Calculate metadata
    result.metadata!.itemCount = result.data.length
    result.metadata!.totalWeight = result.data.reduce((sum, item) => sum + item.weight_grams * item.quantity, 0)

    if (result.data.length === 0) {
      result.success = false
      result.errors.push('No gear items found in the LighterPack page')
    }

  } catch (error) {
    result.success = false
    result.errors.push(`Failed to parse HTML: ${error instanceof Error ? error.message : 'Unknown error'}`)
  }

  return result
}

/**
 * Validate LighterPack URL format
 */
function isValidLighterPackUrl(url: string): boolean {
  try {
    const urlObj = new URL(url)
    return urlObj.hostname === 'lighterpack.com' && urlObj.pathname.startsWith('/r/')
  } catch {
    return false
  }
}

/**
 * Extract chartData parameter from the HTML
 */
function extractChartData(html: string): any | null {
  try {
    // Look for chartData parameter in the HTML
    const chartDataMatch = html.match(/chartData["\s]*=["\s]*([^"]+)/)
    if (!chartDataMatch) return null

    // Decode the URL-encoded JSON string
    const encodedData = chartDataMatch[1]
    const decodedData = decodeURIComponent(encodedData)

    return JSON.parse(decodedData)
  } catch {
    return null
  }
}

/**
 * Parse the chartData JSON structure
 */
function parseChartData(chartData: any): ParsedGearItem[] {
  const items: ParsedGearItem[] = []

  try {
