import { describe, it, expect } from 'vitest'
import { parseLighterPackHtml, createLighterPackInstructions } from './lighterpackParser'

describe('LighterPack Parser', () => {
  describe('parseLighterPackHtml', () => {
    it('should handle empty HTML gracefully', () => {
      const html = '<html><head><title>Empty List</title></head><body></body></html>'

      const result = parseLighterPackHtml(html)

      expect(result.success).toBe(false)
      expect(result.data).toHaveLength(0)
      expect(result.errors).toContain('No gear items found in the LighterPack page')
      expect(result.metadata?.listName).toBe('Empty List')
    })

    it('should extract title from HTML', () => {
      const html = '<html><head><title>My Backpacking Gear</title></head><body></body></html>'

      const result = parseLighterPackHtml(html)

      expect(result.metadata?.listName).toBe('My Backpacking Gear')
    })

    it('should parse chartData if present', () => {
      // Mock HTML with embedded chartData
      const html = `
        <html>
          <head><title>Test List</title></head>
          <body>
            <script>
              var chartData = "%7B%22children%22%3A%5B%7B%22name%22%3A%22%F0%9F%A5%BE%20Footwear%22%2C%22children%22%3A%5B%7B%22name%22%3A%22Trail%20Runners%22%2C%22weight%22%3A500%2C%22qty%22%3A1%2C%22worn%22%3Afalse%7D%5D%7D%5D%7D";
            </script>
          </body>
        </html>
      `

      const result = parseLighterPackHtml(html)

      // This test demonstrates the structure - actual parsing would need real chartData
      expect(result.metadata?.listName).toBe('Test List')
    })

    it('should handle malformed HTML without crashing', () => {
      const html = '<html><invalid><broken>content</html>'

      const result = parseLighterPackHtml(html)

      // Should not throw and should provide useful error info
      expect(result).toBeDefined()
      expect(Array.isArray(result.data)).toBe(true)
      expect(Array.isArray(result.errors)).toBe(true)
    })
  })

  describe('createLighterPackInstructions', () => {
    it('should provide clear user instructions', () => {
      const instructions = createLighterPackInstructions()

      expect(instructions).toContain('CSV Export')
      expect(instructions).toContain('Manual Copy')
      expect(instructions).toContain('View Source')
      expect(typeof instructions).toBe('string')
      expect(instructions.length).toBeGreaterThan(100)
    })
  })

  // Additional helper function tests
  describe('helper functions', () => {
    it('should validate LighterPack URLs', () => {
      // We'd need to export the validation function to test it
      // For now, this is a placeholder for URL validation tests
      const validUrls = [
        'https://lighterpack.com/r/abc123',
        'https://lighterpack.com/r/test'
      ]

      const invalidUrls = [
        'https://example.com/r/abc123',
        'https://lighterpack.com/invalid',
        'not-a-url'
      ]

      // These tests would validate URL format checking
      expect(validUrls.length).toBeGreaterThan(0)
      expect(invalidUrls.length).toBeGreaterThan(0)
    })
  })
})

