import { useState, lazy, Suspense } from 'react'
import { useAuth } from '@/contexts/AuthContext'
import { useSidebar } from '@/contexts/SidebarContext'
import { AccountSettingsCard } from '@/components/account/AccountSettingsCard'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import { PanelLeft } from 'lucide-react'
import type { ParsedGearItem } from '@/utils/csvParser'
import { useBulkCreateGear } from '@/hooks/useGearData'

// Lazy load the import component (same as ProfilePage currently uses)
const ImportGearForm = lazy(() => import('@/components/gear/ImportGearForm').then(m => ({ default: m.ImportGearForm })))

export function AccountPage() {
  const { user, signOut } = useAuth()
  const { toggleSidebar } = useSidebar()
  const [showImport, setShowImport] = useState(false)
  const bulkCreateGearMutation = useBulkCreateGear(user?.id)

  const handleImportGear = async (items: ParsedGearItem[]) => {
    if (!user) return

    try {
      // Transform ParsedGearItem to match our database schema
      const gearItems = items.map(item => ({
        name: item.name,
        brand: item.brand || null,
        weight_grams: item.weight_grams,
        category: item.category,
        quantity: item.quantity,
        worn: item.worn,
        consumable: item.consumable,
        price: item.price || null,
        notes: item.notes || null,
        description: item.description || null,
        image_url: null
      }))

      await bulkCreateGearMutation.mutateAsync(gearItems)

      // Close import form
      setShowImport(false)
    } catch (error) {
      // Error is already handled by the mutation's onError
      console.error('Failed to import gear:', error)
    }
  }

  const handleExportData = async () => {
    // TODO: Implement data export functionality
    console.log('Export data functionality coming soon')
  }

  return (
    <div className="min-h-[calc(100vh-4rem)] lg:min-h-screen">
      <div className="container mx-auto px-4 py-6 sm:py-8">
        {/* Page Header */}
        <div className="mb-6 sm:mb-8">
          <div className="flex items-start gap-4">
            <Button
              variant="ghost"
              size="icon"
              onClick={toggleSidebar}
              className="hidden lg:flex mt-1 h-8 w-8 hover:bg-accent rounded-md flex-shrink-0"
              aria-label="Toggle sidebar"
            >
              <PanelLeft className="h-4 w-4" />
            </Button>
            <div className="flex-1">
              <h1 className="text-2xl sm:text-3xl font-bold tracking-tight">Account Settings</h1>
              <p className="text-muted-foreground mt-1 text-sm sm:text-base">
                Manage your account, subscription, and preferences
              </p>
            </div>
          </div>
        </div>

        {/* Show Import Form if active (temporary - will move to gear page) */}
        {showImport && (
          <div className="mb-6">
            <Suspense fallback={
              <div className="border-border/40 shadow-sm p-6 rounded-lg">
                <div className="space-y-4">
                  <Skeleton className="h-8 w-48" />
                  <Skeleton className="h-20 w-full" />
                  <Skeleton className="h-10 w-32" />
                </div>
              </div>
            }>
              <ImportGearForm 
                onCancel={() => setShowImport(false)}
                onImportComplete={handleImportGear}
              />
            </Suspense>
          </div>
        )}

        {/* Account Settings Cards */}
        {!showImport && (
          <AccountSettingsCard
            user={user}
            onSignOut={signOut}
            onImportData={() => setShowImport(true)}
            onExportData={handleExportData}
          />
        )}
      </div>
    </div>
  )
}

