        consumable: item.consumable,
        price: item.price || null,
        notes: item.notes || null,
        description: item.description || null,
        image_url: null
      }))

      await bulkCreateGearMutation.mutateAsync(gearItems)

      // Close import form
      setShowImport(false)
    } catch (error) {
      // Error is already handled by the mutation's onError
      console.error('Failed to import gear:', error)
