import { CollectionCompactRow, type CompactRowAction } from '@/components/shared/CollectionCompactRow'
import { Edit2, Trash2, Copy } from 'lucide-react'
import { Badge } from '@/components/ui/badge'
import type { GearItem, WeightUnit } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'

interface GearCompactRowProps {
  item: GearItem
  weightUnit: WeightUnit
  onEdit: (item: GearItem) => void
  onDelete: (item: GearItem) => void
  onDuplicate?: (item: Omit<GearItem, 'id' | 'created_at' | 'updated_at' | 'user_id'>) => void
  onClick?: (item: GearItem) => void
}

export function GearCompactRow({ 
  item, 
  weightUnit, 
  onEdit, 
  onDelete,
  onDuplicate,
  onClick 
}: GearCompactRowProps) {
  // Build subtitle from brand, model, and description (matches the screenshot format)
  const subtitle = [item.brand, item.model, item.description]
    .filter(Boolean)
    .join(', ')

  // Category badge
  const categoryBadge = (
    <Badge variant="outline" className="text-xs px-2 py-0">
      {item.category}
    </Badge>
  )

  // Properties badges (compact version)
  const properties = (
    <div className="flex gap-1">
      {item.worn && (
        <span className="text-xs text-muted-foreground">Worn</span>
      )}
      {item.consumable && (
        <span className="text-xs text-muted-foreground">Consumable</span>
      )}
    </div>
  )

  // Data columns for compact view: Category, Weight, Qty, Total, Properties
  const totalWeight = item.weight_grams * item.quantity
  const columns = [
    categoryBadge, // Category
    formatWeightWithUnit(item.weight_grams, weightUnit), // Weight
    item.quantity, // Qty  
    formatWeightWithUnit(totalWeight, weightUnit), // Total
    properties // Properties (Worn/Consumable)
  ]

  // Build actions
  const actions: CompactRowAction[] = [
    {
      label: 'Edit',
      icon: <Edit2 className="mr-2 h-4 w-4" />,
      onClick: () => onEdit(item)
    },
    ...(onDuplicate ? [{
      label: 'Duplicate',
      icon: <Copy className="mr-2 h-4 w-4" />,
      onClick: () => {
        const { id, created_at, updated_at, user_id, ...cloneData } = item
        const newItem = { ...cloneData, name: `${cloneData.name} (Copy)` }
        onDuplicate(newItem)
      }
    }] : []),
    {
      label: 'Delete',
      icon: <Trash2 className="mr-2 h-4 w-4" />,
      onClick: () => onDelete(item),
      variant: 'destructive' as const
    }
  ]

  return (
    <CollectionCompactRow
      title={item.name}
      subtitle={subtitle}
      columns={columns}
      actions={actions}
      onClick={onClick ? () => onClick(item) : undefined}
    />
  )
}

import { memo, useMemo } from 'react'
import { Card, CardContent, CardFooter } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Edit2, Trash2, Package, Weight, Hash, ImageOff } from 'lucide-react'
import type { GearItem, WeightUnit } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'

interface GearCardProps {
  item: GearItem
  weightUnit?: WeightUnit
  onEdit: (item: GearItem) => void
  onDelete: (item: GearItem) => void
}

export const GearCard = memo(function GearCard({ item, weightUnit = 'g', onEdit, onDelete }: GearCardProps) {
  const totalWeight = useMemo(() => item.weight_grams * item.quantity, [item.weight_grams, item.quantity])

  return (
    <Card className="hover:shadow-md transition-all duration-150 hover:scale-[1.01] border-border/40 h-full flex flex-col relative active:scale-[0.99]">
      {/* Category Badge - always in top-right corner */}
      <Badge variant="outline" className="absolute top-4 right-4 z-10 bg-background/90 backdrop-blur-sm">
        {item.category}
      </Badge>

      {/* Image Section - always show on desktop for alignment, conditional on mobile */}
      <div className={`relative h-32 sm:h-48 bg-muted overflow-hidden flex items-center justify-center ${
        !item.image_url ? 'hidden md:flex' : ''
      }`}>
        {item.image_url ? (
          <img
            src={item.image_url}
            alt={item.name}
            className="w-full h-full object-cover"
            onError={(e) => {
              // Show placeholder on error instead of hiding
              const img = e.currentTarget
              img.style.display = 'none'
              const placeholder = img.nextElementSibling as HTMLElement
              if (placeholder) {
                placeholder.style.display = 'flex'
              }
            }}
          />
        ) : null}
        {/* Placeholder - shown when no image or on error */}
        <div className={`${item.image_url ? 'hidden' : ''} absolute inset-0 flex items-center justify-center`}>
          <ImageOff className="h-12 w-12 text-muted-foreground/30" />
        </div>
      </div>

      <CardContent className="p-6 flex-1 flex flex-col">
        <div className="space-y-4 flex-1">
          {/* Header with consistent height */}
          <div className="min-h-[4rem]">
            <h3 className="text-base font-medium text-muted-foreground">
              {item.name}
            </h3>
            <p className="text-lg font-semibold line-clamp-1 mt-1">
              {item.model || item.description || item.brand || 'No model specified'}
            </p>
            {item.brand && (item.model || item.description) && (
              <p className="text-sm text-muted-foreground mt-0.5">
                {item.brand}
              </p>
            )}
          </div>

          {/* Stats Grid */}
          <div className="grid grid-cols-3 gap-4 py-4 border-y border-border/40">
            <div className="text-center">
              <div className="flex items-center justify-center mb-1 text-muted-foreground">
                <Weight className="h-3 w-3 mr-1" />
                <span className="text-xs">Weight</span>
              </div>
              <p className="text-sm font-medium">{formatWeightWithUnit(item.weight_grams, weightUnit)}</p>
            </div>
            <div className="text-center">
              <div className="flex items-center justify-center mb-1 text-muted-foreground">
                <Hash className="h-3 w-3 mr-1" />
                <span className="text-xs">Qty</span>
              </div>
              <p className="text-sm font-medium">{item.quantity}</p>
            </div>
            <div className="text-center">
              <div className="flex items-center justify-center mb-1 text-muted-foreground">
                <Package className="h-3 w-3 mr-1" />
                <span className="text-xs">Total</span>
              </div>
              <p className="text-sm font-medium">{formatWeightWithUnit(totalWeight, weightUnit)}</p>
            </div>
          </div>


          {/* Properties */}
          {(item.worn || item.consumable) && (
            <div className="flex gap-2">
              {item.worn && (
                <Badge variant="secondary" className="text-xs">
                  Worn
                </Badge>
              )}
              {item.consumable && (
                <Badge variant="secondary" className="text-xs">
                  Consumable
                </Badge>
              )}
            </div>
          )}

          {/* Notes */}
          {item.notes && (
            <p className="text-sm text-muted-foreground line-clamp-2">
              {item.notes}
            </p>
          )}

          {/* Price */}
          {item.price && (
            <div className="flex items-center justify-between text-sm">
              <span className="text-muted-foreground">Price</span>
              <span className="font-medium">${item.price.toFixed(2)}</span>
            </div>
          )}
        </div>
      </CardContent>
      <CardFooter className="p-4 pt-0 flex gap-2 mt-auto">
        <Button
          variant="outline"
          size="sm"
          className="flex-1"
          onClick={() => onEdit(item)}
        >
          <Edit2 className="h-3 w-3 mr-1" />
          Edit
        </Button>
        <Button
          variant="outline"
          size="sm"
          className="flex-1 text-destructive hover:text-destructive"
          onClick={() => onDelete(item)}
        >
          <Trash2 className="h-3 w-3 mr-1" />
          Delete
        </Button>
      </CardFooter>
    </Card>
  )
})

